def get_title(value):
    if value in JD_LIBRARY:
        return JD_LIBRARY[value]['title']
    if value in GENERIC_TITLES:
        return GENERIC_TITLES[value][0]
    return ''


def get_html(value):
    if value in JD_LIBRARY:
        return JD_LIBRARY[value]['html']
    if value in GENERIC_TITLES:
        return JD_LIBRARY.get(GENERIC_TITLES[value][1], {}).get('html')
    return None


def specific_choices():
    return [(k, JD_LIBRARY[k]['title']) for k in SPECIFIC_ORDER]


def generic_choices():
    return [(k, v[0]) for k, v in GENERIC_TITLES.items()]


def grouped_choices():
    groups = []
    for c in CATEGORY_ORDER:
        items = [(k, JD_LIBRARY[k]['title']) for k in SPECIFIC_ORDER if CATEGORIES.get(k) == c]
        items += [(k, v[0]) for k, v in GENERIC_TITLES.items() if CATEGORIES.get(k) == c]
        if items:
            groups.append((c, items))
    return groups
